// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2, IVault} from "../src/DnGmxBatchingManager.sol";

contract MockERC20 is IERC20 {
    function totalSupply() external pure returns (uint256) { return 1e30; }
    function balanceOf(address) external pure returns (uint256) { return 1e30; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function allowance(address, address) external pure returns (uint256) { return type(uint256).max; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}

contract MockGlpManager is IGlpManager {
    MockVault public mv;
    constructor() { mv = new MockVault(); }
    function vault() external view returns (address) { return address(mv); }
}

contract MockVault is IVault {
    function getMinPrice(address) external pure returns (uint256) { return 1e30; }
}

contract MockRewardRouter is IRewardRouterV2 {
    uint256 public glpOut = 5e17;
    function mintAndStakeGlp(address, uint256, uint256, uint256) external pure returns (uint256) { return 5e17; }
}

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockERC20 sGlp;
    MockERC20 usdc;
    MockGlpManager glpManager;
    MockRewardRouter router;
    address constant VAULT = address(0xA11CE);

    function setUp() public {
        sGlp = new MockERC20();
        usdc = new MockERC20();
        glpManager = new MockGlpManager();
        router = new MockRewardRouter();
        c = new DnGmxBatchingManager();
        c.initialize(IERC20(address(sGlp)), IERC20(address(usdc)), IRewardRouterV2(address(router)), IGlpManager(address(glpManager)), VAULT, address(this));
    }

    function testFuzz_property(uint256 amount, uint256 minUSDG, uint256 warpTo) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(minUSDG <= type(uint256).max / 1e12);
        vm.assume(warpTo > 15 minutes + 1);

        // a token deposit from the (mocked) junior vault credits the tracked GLP balance
        vm.prank(VAULT);
        c.depositToken(address(sGlp), amount, minUSDG);

        assertTrue(c.dnGmxJuniorVaultGlpBalance() > 0, "precondition: deposit recorded");

        vm.warp(warpTo);
        c.executeBatchDeposit();

        // RULE: after a completed batch deposit the tracked balance must be cleared to zero
        assertTrue(c.dnGmxJuniorVaultGlpBalance() == 0, "tracked GLP balance must be cleared after batch deposit");
    }
}
